import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Config/Assets/image_png.dart';import '../../../../Config/Routes/route_name.dart';import 'package:zan/main.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Resources/app_colors.dart';import 'build_social_login_button.dart';class AuthenticationSplit2 extends StatelessWidget {  const AuthenticationSplit2({    super.key,  });  @override  Widget build(BuildContext context) {    final isSmall = context.isSmallScreen;    return Align(      alignment: isSmall ? Alignment.bottomCenter : Alignment.centerLeft,      child: Container(        padding: EdgeInsets.only(top: isSmall ? 0 : 20.h),        width: isSmall ? 1.sw : .5.sw,        height: isSmall ? 0.5.sh : null,        decoration: BoxDecoration(            color: AppColors.backgroundColor,            borderRadius: isSmall                ? BorderRadius.only(                    topRight: Radius.circular(20.r),                    topLeft: Radius.circular(20.r),                  )                : null,            boxShadow: isSmall                ? [                    BoxShadow(                      color: Colors.grey[500]!,                      spreadRadius: 2,                      blurRadius: 10,                      offset: const Offset(0, 3), // changes position of shadow                    ),                  ]                : null),        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          mainAxisSize: MainAxisSize.max,          children: [            _buildTitleSplit(context),            Column(              mainAxisAlignment: MainAxisAlignment.spaceAround,              children: [                BuildSocialLoginButton(                  imagePath: AppImagesPng.apple,                  text: context.local.LoginByApple,                  backgroundColor: Colors.black,                  onPressed: () {                    // Handle Apple login                  },                ),                8.verticalSpace,                BuildSocialLoginButton(                  imagePath: AppImagesPng.facebook,                  text: context.local.LoginByFacebook,                  backgroundColor: Color(0xff3a65a4),                  onPressed: () {                    // Handle Facebook login                  },                ),                8.verticalSpace,                BuildSocialLoginButton(                  imagePath: AppImagesPng.google,                  text: context.local.LoginByGoogle,                  backgroundColor: Colors.white,                  textColor: Colors.black,                  onPressed: () {                    // Handle Google login                  },                ),                24.verticalSpace,                TextButton(                  onPressed: () {                    kNavigationService.clearAndNavigateTo(AppRoutes.main);                  },                  child: Text(                    context.local.SkipLogin,                    style: AppTextStyles.bodyMediumBold,                    textAlign: TextAlign.center,                  ),                ),              ],            )          ],        ),      ),    );  }  Container _buildTitleSplit(BuildContext context) => Container(        padding: EdgeInsets.all(15).w,        width: 318.w,        child: Text(          context.local.TitleStartApp,          style: AppTextStyles.h4Bold,          textAlign: TextAlign.center,          maxLines: context.local.TitleStartApp.length,        ),      );}